#!/usr/bin/env node
// summarize-test-failures.js
//
// Turn a `cargo test --workspace` log into a human-readable report for the
// nightly-bump PR. The point of the automation is not just "it failed" but
// "here is the scope of the breakage" -- the same scoping the runbook exists
// to produce by hand.
//
// Usage: node summarize-test-failures.js <log-file> <target-nightly>
// Emits markdown on stdout.

"use strict";

const fs = require("fs");

const logPath = process.argv[2];
const target = process.argv[3] || "the new nightly";
const log = fs.readFileSync(logPath, "utf8");
const lines = log.split("\n");

// Unique compiler error messages (clippy_utils / rustc_hir API breakage shows
// up here as `error[EXXXX]:` or `error:` lines).
const compileErrors = new Set();
// Individual failing test paths (`test path::to::test ... FAILED`).
const failedTests = new Set();
// UI fixture files referenced in the output -- these map to specific lints.
const uiFixtures = new Set();

for (const line of lines) {
  const err = line.match(/^error(\[[A-Z0-9]+\])?:\s+(.*)$/);
  if (err) {
    const msg = err[2].trim();
    if (msg) compileErrors.add(msg);
  }
  const tst = line.match(/test\s+(\S+)\s+\.\.\.\s+FAILED/);
  if (tst) failedTests.add(tst[1]);
  const ui = line.match(/ui\/([A-Za-z0-9_]+\.rs)/);
  if (ui) uiFixtures.add(ui[1].replace(/\.rs$/, ""));
}

const hasCompileError = compileErrors.size > 0;
const hasTestFailure = failedTests.size > 0;
const passed = !hasCompileError && !hasTestFailure;

const out = [];
out.push(`## Nightly bump to \`${target}\``);
out.push("");
out.push(`_Generated by the Nightly Bump workflow._`);
out.push("");

if (passed) {
  out.push("✅ **The full test suite passed** under the new nightly.");
  out.push("");
  out.push(
    "This PR is ready for a human to review and merge. Before merging, eyeball the " +
      "`git diff` of any regenerated `.stderr` UI fixtures to confirm the diagnostic " +
      "changes are cosmetic (see the runbook's *Blessing UI Tests* section)."
  );
  out.push("");
} else {
  out.push("❌ **The automated bump did not pass.** This is expected when the pin has gone stale.");
  out.push("");
  out.push(
    "The list below scopes the work -- it is the same inventory the runbook asks you to " +
      "produce by hand. Follow the runbook's *Common Breakages* sections to fix, then either " +
      "push the fix to this branch or let the next scheduled run try again."
  );
  out.push("");

  if (hasCompileError) {
    out.push("### Compile errors (likely `clippy_utils` / `rustc_hir` API breakage)");
    out.push("");
    out.push("These usually mean the lint crate no longer builds against the new nightly:");
    out.push("");
    for (const e of [...compileErrors].slice(0, 40)) {
      out.push(`- \`${e}\``);
    }
    if (compileErrors.size > 40) {
      out.push(`- _...and ${compileErrors.size - 40} more (see the full workflow log)._`);
    }
    out.push("");
  }

  if (uiFixtures.size > 0) {
    out.push("### Likely affected lints (UI fixtures)");
    out.push("");
    out.push(
      "The following UI fixtures appeared in the failure output. Each corresponds to a lint " +
        "in `soroban_cost_lints/src/lib.rs`; check whether its diagnostic shape changed:"
    );
    out.push("");
    for (const f of [...uiFixtures].sort()) {
      out.push(`- \`${f}\``);
    }
    out.push("");
  }

  if (hasTestFailure) {
    out.push("### Failing tests");
    out.push("");
    for (const t of [...failedTests].sort()) {
      out.push(`- \`${t}\``);
    }
    out.push("");
  }

  out.push("### Next steps");
  out.push("");
  out.push("1. Read [docs/NIGHTLY_UPGRADE_RUNBOOK.md](docs/NIGHTLY_UPGRADE_RUNBOOK.md).");
  out.push(
    "2. If a `clippy_utils` rev was resolved incorrectly, re-run the workflow with the " +
      "`clippy_rev` input set to the correct 40-char SHA."
  );
  out.push("3. Push fixes to this branch; the PR updates in place (no new PR is opened).");
  out.push("");
}

process.stdout.write(out.join("\n") + "\n");
